-- =====================================================================
-- 04b_insert_data_inserts.sql  -  INSERT-based alternative to 04_insert_data.sql
-- Generated by scripts/generate_dataset.py --inserts. Use it when \copy is not
-- available (e.g. a GUI client such as DBeaver or pgAdmin's query tool).
-- It needs no CSV files and can be run from any folder. Slower than \copy.
-- Expected rows: customers 5,000, products 300, orders 50,000, order_items 120,000, payments 50,000, payment_staging 2,640
-- =====================================================================
SET search_path TO sokomart;

BEGIN;







SELECT setval(pg_get_serial_sequence('sokomart.customers', 'customer_id'), (SELECT COALESCE(MAX(customer_id), 0) + 1 FROM sokomart.customers), false);
SELECT setval(pg_get_serial_sequence('sokomart.products', 'product_id'), (SELECT COALESCE(MAX(product_id), 0) + 1 FROM sokomart.products), false);
SELECT setval(pg_get_serial_sequence('sokomart.orders', 'order_id'), (SELECT COALESCE(MAX(order_id), 0) + 1 FROM sokomart.orders), false);
SELECT setval(pg_get_serial_sequence('sokomart.order_items', 'order_item_id'), (SELECT COALESCE(MAX(order_item_id), 0) + 1 FROM sokomart.order_items), false);
SELECT setval(pg_get_serial_sequence('sokomart.payments', 'payment_id'), (SELECT COALESCE(MAX(payment_id), 0) + 1 FROM sokomart.payments), false);
SELECT setval(pg_get_serial_sequence('sokomart.payment_staging', 'staging_id'), (SELECT COALESCE(MAX(staging_id), 0) + 1 FROM sokomart.payment_staging), false);

COMMIT;

ANALYZE sokomart.customers, sokomart.products, sokomart.orders, sokomart.order_items, sokomart.payments, sokomart.payment_staging;
SELECT * FROM customers;

-- =====================================================================
-- 05_indexes.sql  -  secondary indexes (access paths)
--
-- Kept OUT of 03_create_tables.sql on purpose: for Questions 21-22 you run
-- EXPLAIN ANALYZE on a query BEFORE this file, run this file, and run the
-- same EXPLAIN ANALYZE again to compare the plans.
--
-- Primary keys and UNIQUE constraints already have indexes. Postgres does
-- NOT index foreign-key columns automatically - most of the indexes below are
-- exactly those join columns.
--
-- Safe to re-run (IF NOT EXISTS). To go back to "before", run the DROP block
-- at the bottom (commented out).
-- =====================================================================
\set ON_ERROR_STOP on
SET search_path TO sokomart, public;

-- customer access paths
CREATE INDEX IF NOT EXISTS idx_customers_county            ON sokomart.customers (county);
CREATE INDEX IF NOT EXISTS idx_customers_registration_date ON sokomart.customers (registration_date);

-- product access paths
CREATE INDEX IF NOT EXISTS idx_products_category           ON sokomart.products (category);

-- order access paths
CREATE INDEX IF NOT EXISTS idx_orders_customer_id          ON sokomart.orders (customer_id);
CREATE INDEX IF NOT EXISTS idx_orders_order_date           ON sokomart.orders (order_date);
CREATE INDEX IF NOT EXISTS idx_orders_status_date          ON sokomart.orders (order_status, order_date);
CREATE INDEX IF NOT EXISTS idx_orders_customer_date        ON sokomart.orders (customer_id, order_date);

-- order item access paths (uq_order_items_order_product already covers order_id lookups)
CREATE INDEX IF NOT EXISTS idx_order_items_product_id      ON sokomart.order_items (product_id);

-- payment access paths
CREATE INDEX IF NOT EXISTS idx_payments_order_id           ON sokomart.payments (order_id);
CREATE INDEX IF NOT EXISTS idx_payments_status_method      ON sokomart.payments (payment_status, payment_method);
CREATE INDEX IF NOT EXISTS idx_payments_payment_date       ON sokomart.payments (payment_date);

-- history tables
CREATE INDEX IF NOT EXISTS idx_price_history_product_id    ON sokomart.product_price_history (product_id);
CREATE INDEX IF NOT EXISTS idx_status_history_order_id     ON sokomart.order_status_history (order_id);

ANALYZE sokomart.customers, sokomart.products, sokomart.orders,
        sokomart.order_items, sokomart.payments;

\echo 05_indexes.sql finished

