-- Q1: Big spenders of 2025

WITH customer_spending AS (
    SELECT
        c.customer_id,
        c.first_name || ' ' || c.last_name AS full_name,
        c.county,
        SUM(i.line_total) AS total_spent_2025
    FROM sokomart.customers c
    JOIN sokomart.orders o
        ON c.customer_id = o.customer_id
    JOIN sokomart.order_items i
        ON o.order_id = i.order_id
    WHERE o.order_status = 'completed'
      AND o.order_date >= '2025-01-01'
      AND o.order_date < '2026-01-01'
    GROUP BY
        c.customer_id,
        c.first_name,
        c.last_name,
        c.county
)

SELECT
    customer_id,
    full_name,
    county,
    total_spent_2025,
    (SELECT AVG(total_spent_2025)
     FROM customer_spending) AS avg_spent_2025,
    total_spent_2025 -
    (SELECT AVG(total_spent_2025)
     FROM customer_spending) AS amount_above_avg
FROM customer_spending
WHERE total_spent_2025 >
    (SELECT AVG(total_spent_2025)
     FROM customer_spending)
ORDER BY total_spent_2025 DESC;


-- Q2: Premium-priced products

SELECT
    p.product_id,
    p.product_name,
    p.category,
    p.unit_price,

    (SELECT AVG(p2.unit_price)
     FROM sokomart.products p2
     WHERE p2.category = p.category
    ) AS category_avg_price,

    p.unit_price -
    (SELECT AVG(p2.unit_price)
     FROM sokomart.products p2
     WHERE p2.category = p.category
    ) AS price_gap

FROM sokomart.products p

WHERE p.product_status = 'active'
  AND p.unit_price >
      (SELECT AVG(p2.unit_price)
       FROM sokomart.products p2
       WHERE p2.category = p.category
      )
ORDER BY p.category, price_gap DESC;


-- Q3: Monthly Profit and Loss for 2026

WITH months AS (
    SELECT generate_series(
        DATE '2026-01-01',
        DATE '2026-10-01',
        INTERVAL '1 month'
    )::DATE AS month_start
),

completed_order_lines AS (
    SELECT
        DATE_TRUNC('month', o.order_date)::DATE AS month_start,
        oi.line_total AS revenue,
        oi.quantity * p.cost_price AS cost
    FROM sokomart.orders o
    JOIN sokomart.order_items oi
        ON o.order_id = oi.order_id
    JOIN sokomart.products p
        ON oi.product_id = p.product_id
    WHERE o.order_status = 'completed'
      AND o.order_date >= '2026-01-01'
      AND o.order_date < '2026-11-01'
),

monthly_totals AS (
    SELECT
        month_start,
        SUM(revenue) AS revenue,
        SUM(cost) AS cost
    FROM completed_order_lines
    GROUP BY month_start
),

monthly_profit AS (
    SELECT
        m.month_start,
        COALESCE(mt.revenue, 0) AS revenue,
        COALESCE(mt.cost, 0) AS cost,
        COALESCE(mt.revenue, 0) - COALESCE(mt.cost, 0)
            AS gross_profit
    FROM months m
    LEFT JOIN monthly_totals mt
        ON m.month_start = mt.month_start
)

SELECT
    TO_CHAR(month_start, 'YYYY-MM') AS month,
    revenue,
    cost,
    gross_profit,
    CASE
        WHEN revenue = 0 THEN NULL
        ELSE ROUND((gross_profit / revenue) * 100, 2)
    END AS margin_pct
FROM monthly_profit
ORDER BY month_start;
